const locale = (en,ru,uz) => ({en,ru,uz});
export const pages = [
  {slug:'',group:'home',title:locale('Telegram Stars and Premium API — Fragment Donor SDKs','API Telegram Stars и Premium — SDK Fragment Donor','Telegram Stars va Premium API — Fragment Donor SDKlar'),description:locale('Integrate Telegram Stars gifting and Premium with seven independent SDKs. Public service API, safe retry handling, and practical examples.','Интеграция Telegram Stars и Premium: семь независимых SDK, открытый API, безопасная обработка ошибок и примеры.','Telegram Stars va Premium integratsiyasi: yetti SDK, authsiz servis API, xavfsiz retry qoidalari va amaliy misollar.'),body:locale(
    ['Fragment Donor exposes four endpoints for checking a Telegram username, gifting Stars or Premium, and reading TON/USDT balances. Python, Node.js/TypeScript, PHP, .NET, Go, Rust, and Ruby clients share one tested contract.','Direct use needs no service account. The optional Api-Key is a TonConsole provider key. Purchases still need your own wallet mnemonic and Fragment cookie.','The default quota is 30 requests per IP per minute across all four endpoints. Follow 429 FLOOD_WAIT and Retry-After. A request timeout does not prove that a payment failed: purchase calls are never retried automatically.'],
    ['Fragment Donor предоставляет четыре эндпоинта: проверка Telegram username, подарок Stars или Premium и баланс TON/USDT. Клиенты Python, Node.js/TypeScript, PHP, .NET, Go, Rust и Ruby используют общий проверяемый контракт.','Для прямого доступа не нужен аккаунт сервиса. Необязательный Api-Key — ключ провайдера TonConsole. Для покупки нужны mnemonic своего кошелька и cookie Fragment.','По умолчанию лимит общий для четырёх эндпоинтов: 30 запросов в минуту на IP. Учитывайте 429 FLOOD_WAIT и Retry-After. Timeout не доказывает отсутствие платежа: SDK не повторяют покупки автоматически.'],
    ['Fragment Donor to‘rtta endpoint beradi: Telegram username tekshirish, Stars yoki Premium sovg‘a qilish va TON/USDT balansini ko‘rish. Python, Node.js/TypeScript, PHP, .NET, Go, Rust va Ruby klientlari umumiy tekshiriladigan kontraktdan foydalanadi.','Bevosita kirish uchun servis akkaunti kerak emas. Ixtiyoriy Api-Key — TonConsole provider kaliti. Xarid uchun o‘z hamyoningiz mnemonic’i va Fragment cookie’si kerak.','Standart limit to‘rtta endpoint uchun umumiy: bir IP’ga daqiqasiga 30 so‘rov. 429 FLOOD_WAIT va Retry-After’ga rioya qiling. Timeout to‘lov bajarilmaganini isbotlamaydi: SDK xaridni avtomatik takrorlamaydi.']),code:'curl "https://fragment.donor.uz/get-user-info/?username=durov"'},
  {slug:'reference/get-user-info',group:'reference',title:locale('Check Telegram username and Premium status','Проверка Telegram username и статуса Premium','Telegram username va Premium holatini tekshirish'),description:locale('GET get-user-info API: username validation, Premium status, errors, and an account-free cURL example.','GET get-user-info: проверка username, статус Premium, ошибки и пример cURL без аккаунта сервиса.','GET get-user-info API: username validatsiyasi, Premium holati, xatolar va kalitsiz cURL misoli.'),body:locale(
    ['Send GET /get-user-info/ with username as a query parameter. Both durov and @durov are accepted. The backend allows an initial ASCII letter followed by 3–31 ASCII letters, digits, or underscores.','No wallet credential is needed. A successful response has ok, username, and is_premium. A missing/non-user result can contain reason instead of error. Preserve unknown response fields.'],
    ['Отправьте GET /get-user-info/ с query-параметром username. Допустимы durov и @durov. Backend принимает первую ASCII-букву и ещё 3–31 букву, цифру или подчёркивание.','Данные кошелька не нужны. Успешный ответ содержит ok, username и is_premium. При отсутствии пользователя может вернуться reason вместо error. Не удаляйте неизвестные поля ответа.'],
    ['GET /get-user-info/ so‘rovida username query parametri yuboriladi. durov ham, @durov ham qabul qilinadi. Backend birinchi ASCII harf va undan keyin 3–31 ta harf, raqam yoki pastki chiziqqa ruxsat beradi.','Hamyon credentiallari kerak emas. Muvaffaqiyatli javobda ok, username va is_premium bor. Foydalanuvchi topilmasa error o‘rniga reason qaytishi mumkin. Noma’lum qo‘shimcha maydonlarni saqlang.']),code:'curl "https://fragment.donor.uz/get-user-info/?username=durov"',response:'{"ok":true,"username":"durov","is_premium":false}'},
  {slug:'reference/buy-stars',group:'reference',title:locale('Buy and gift Telegram Stars through the API','Купить и подарить Telegram Stars через API','API orqali Telegram Stars sotib olish va yuborish'),description:locale('POST buy-stars form fields, mnemonic and cookie headers, TON/USDT payment options, and duplicate-payment prevention.','Параметры POST buy-stars, заголовки mnemonic/cookie, оплата TON/USDT и защита от повторной покупки.','POST buy-stars form parametrlari, mnemonic/cookie headerlari, TON/USDT to‘lovi va takroriy xaridni oldini olish.'),body:locale(
    ['Send POST /buy-stars/ as application/x-www-form-urlencoded, not JSON. Required form fields are username and amount: an integer from 50 to 1,000,000. payment_method is usdt_ton by default; ton is also supported.','Cookie and Mnemonic are required headers. Mnemonic accepts 12, 18, or 24 words. Optional headers: Wallet-Version (auto, v5r1, v4r2, v3r2), Wallet-Address, Proxy, User-Agent, and TonConsole Api-Key. Proxy is an upstream Fragment proxy, not service authentication.','HTTP 200 and ok=true indicate the returned success state. HTTP 400 may include info, unconfirmed, tx_hash, transient, insufficient, or price_guard. Do not discard them or repeat a purchase merely because a response is ambiguous.'],
    ['POST /buy-stars/ принимает application/x-www-form-urlencoded, а не JSON. Обязательны username и amount: целое от 50 до 1 000 000. payment_method по умолчанию usdt_ton; также поддерживается ton.','Обязательны заголовки Cookie и Mnemonic (12, 18 или 24 слова). Необязательны Wallet-Version (auto, v5r1, v4r2, v3r2), Wallet-Address, Proxy, User-Agent и TonConsole Api-Key. Proxy используется для Fragment, а не для авторизации в сервисе.','HTTP 200 с ok=true — состояние успеха в ответе. При HTTP 400 могут быть info, unconfirmed, tx_hash, transient, insufficient или price_guard. Сохраните эти поля; неопределённый ответ не разрешает повторную покупку.'],
    ['POST /buy-stars/ JSON emas, application/x-www-form-urlencoded qabul qiladi. Majburiy username va amount: 50 dan 1 000 000 gacha butun son. payment_method odatda usdt_ton; ton ham ishlaydi.','Cookie va Mnemonic (12, 18 yoki 24 so‘z) majburiy headerlar. Wallet-Version (auto, v5r1, v4r2, v3r2), Wallet-Address, Proxy, User-Agent va TonConsole Api-Key ixtiyoriy. Proxy Fragment bilan aloqa uchun, servis autentifikatsiyasi uchun emas.','HTTP 200 va ok=true javobdagi muvaffaqiyat holatini bildiradi. HTTP 400 javobida info, unconfirmed, tx_hash, transient, insufficient yoki price_guard bo‘lishi mumkin. Ularni saqlang; noaniq javobdan keyin xaridni takrorlamang.']),code:'curl -X POST https://fragment.donor.uz/buy-stars/ \\\n  -H "Cookie: $FRAGMENT_COOKIE" -H "Mnemonic: $WALLET_MNEMONIC" \\\n  --data-urlencode "username=durov" --data "amount=100" \\\n  --data "payment_method=usdt_ton"',sensitive:true},
  {slug:'reference/buy-premium',group:'reference',title:locale('Gift Telegram Premium through the API','Подарить Telegram Premium через API','API orqali Telegram Premium sovg‘a qilish'),description:locale('Telegram Premium gift API: 3, 6, or 12 months, form-urlencoded requests, wallet headers, and safe error handling.','API подарка Telegram Premium: 3, 6 или 12 месяцев, form-urlencoded, заголовки кошелька и обработка ошибок.','Telegram Premium gift API: 3, 6 yoki 12 oy, form-urlencoded so‘rov, hamyon headerlari va xatolarni boshqarish.'),body:locale(
    ['POST /buy-premium/ takes username and duration in form data. Supported durations are exactly 3, 6, or 12 months. payment_method is usdt_ton or ton. Purchase headers are the same as buy-stars.','A recipient already marked Premium is rejected by the inspected backend. Validate this state before offering a purchase. The SDK preserves the server response and never silently chooses a different duration.','This call spends wallet funds. On timeout, transport failure, or uncertain response, reconcile the wallet and recipient state before a human starts another purchase. There is no documented Idempotency-Key guarantee.'],
    ['POST /buy-premium/ принимает username и duration в form data. Поддерживаются только 3, 6 или 12 месяцев. payment_method — usdt_ton или ton. Заголовки те же, что у buy-stars.','Проверенный backend отклоняет пользователя, уже имеющего Premium. Проверяйте состояние перед продажей. SDK сохраняет ответ сервера и не выбирает другой срок автоматически.','Операция тратит средства кошелька. После timeout, сетевой ошибки или неопределённого ответа сначала сверяйте состояние кошелька и получателя. Гарантия Idempotency-Key не документирована.'],
    ['POST /buy-premium/ form data ichida username va duration oladi. Faqat 3, 6 yoki 12 oy qo‘llab-quvvatlanadi. payment_method — usdt_ton yoki ton. Headerlar buy-stars bilan bir xil.','Tekshirilgan backend allaqachon Premium olgan foydalanuvchini rad etadi. Xariddan oldin holatni tekshiring. SDK javobni saqlaydi va muddatni o‘zboshimchalik bilan o‘zgartirmaydi.','Bu chaqiruv hamyon pulini sarflaydi. Timeout, tarmoq xatosi yoki noaniq javobdan keyin qayta xariddan oldin hamyon va qabul qiluvchini tekshiring. Idempotency-Key kafolati hujjatlashtirilmagan.']),code:'curl -X POST https://fragment.donor.uz/buy-premium/ \\\n  -H "Cookie: $FRAGMENT_COOKIE" -H "Mnemonic: $WALLET_MNEMONIC" \\\n  --data-urlencode "username=durov" --data "duration=3"',sensitive:true},
  {slug:'reference/wallet-balance',group:'reference',title:locale('Read TON and USDT wallet balance','Баланс кошелька TON и USDT','TON va USDT hamyon balansini ko‘rish'),description:locale('Wallet balance API returns decimal strings for TON and USDT. Header mapping and precision-safe integration examples.','API баланса возвращает TON и USDT десятичными строками. Заголовки и примеры без потери точности.','Wallet balance API TON va USDT’ni decimal string sifatida beradi. Headerlar va aniqlikni saqlaydigan misollar.'),body:locale(
    ['GET /wallet-balance/ needs Mnemonic, but not Cookie. Wallet-Version, Wallet-Address, and TonConsole Api-Key are optional. The inspected backend also accepts POST; SDK convenience methods use GET.','Keep ton and usdt_ton as strings or arbitrary-precision decimal values. Converting a balance such as 9007199254740993.01 to a JavaScript Number loses precision. This read operation still discloses the submitted mnemonic to the API operator.'],
    ['GET /wallet-balance/ требует Mnemonic, но не Cookie. Wallet-Version, Wallet-Address и TonConsole Api-Key необязательны. Backend также принимает POST; методы SDK используют GET.','Храните ton и usdt_ton строками или decimal произвольной точности. Значение 9007199254740993.01 нельзя точно сохранить в JavaScript Number. Даже чтение баланса передаёт mnemonic оператору API.'],
    ['GET /wallet-balance/ Mnemonic talab qiladi, Cookie kerak emas. Wallet-Version, Wallet-Address va TonConsole Api-Key ixtiyoriy. Backend POST ham qabul qiladi; SDK metodi GET ishlatadi.','ton va usdt_ton qiymatlarini string yoki yuqori aniqlikdagi decimal sifatida saqlang. 9007199254740993.01 qiymati JavaScript Number’da aniqligini yo‘qotadi. Balansni o‘qish ham mnemonic’ni API operatoriga yuboradi.']),code:'curl https://fragment.donor.uz/wallet-balance/ \\\n  -H "Mnemonic: $WALLET_MNEMONIC" -H "Wallet-Version: auto"',response:'{"ok":true,"address":"SYNTHETIC_WALLET_ADDRESS","ton":"2.500000001","usdt_ton":"9007199254740993.01"}',sensitive:true},
  {slug:'guides/rate-limit-flood-wait',group:'guides',title:locale('Handle Telegram Stars API 429, Retry-After, and flood wait','Telegram Stars API: 429, Retry-After и flood wait','Telegram Stars API’da 429, Retry-After va flood wait'),description:locale('Understand the shared IP quota, flood-wait seconds, bounded read retries, and why purchases must not be replayed.','Общий IP-лимит, время flood wait, ограниченные повторы чтения и запрет автоматического повторения покупок.','Umumiy IP limiti, flood wait muddati, chegaralangan read retry va xaridni takrorlamaslik qoidalari.'),body:locale(
    ['The default fixed-minute quota is 30 requests per IP across all four endpoints, including invalid methods and parameters. At the next minute a new quota window begins; separate application users behind one public IP share the quota.','HTTP 429 returns error_code=FLOOD_WAIT, retry_after, flood_wait, and Retry-After. Waiting is opt-in in these SDKs. They understand numeric or HTTP-date Retry-After and JSON retry hints. Choose bounded retries and a maximum acceptable wait.','HTTP 503 RATE_LIMIT_UNAVAILABLE has Retry-After: 5 in the local contract. This means the rate limiter could not authorize execution, not service-key authentication. Read retries can be enabled; purchases always return an error for human reconciliation rather than automatic replay.'],
    ['По умолчанию четыре эндпоинта делят лимит 30 запросов на IP за минутное окно; ошибочные методы и параметры тоже считаются. Новая минута открывает новое окно. Пользователи за одним публичным IP делят квоту.','HTTP 429 содержит error_code=FLOOD_WAIT, retry_after, flood_wait и Retry-After. Автоматическое ожидание в SDK включается явно. Поддерживаются секунды, HTTP-date и JSON-подсказки. Установите предел повторов и ожидания.','HTTP 503 RATE_LIMIT_UNAVAILABLE в локальном контракте возвращает Retry-After: 5. Ограничитель не разрешил выполнение; это не проверка ключа сервиса. Повтор чтения можно включить, а покупка всегда возвращает ошибку без автоматического повторения.'],
    ['To‘rtta endpoint standart holda bir IP uchun minutlik oynada 30 so‘rovni bo‘lishadi; xato metod va parametrlar ham hisoblanadi. Yangi minutda yangi kvota boshlanadi. Bitta tashqi IP ortidagi foydalanuvchilar limitni bo‘lishadi.','HTTP 429 javobida error_code=FLOOD_WAIT, retry_after, flood_wait va Retry-After bor. SDK’da avtomatik kutish alohida yoqiladi. Soniyalar, HTTP-date va JSON kutish maydonlari o‘qiladi. Retry soni va kutishning yuqori chegarasini belgilang.','Lokal kontraktda HTTP 503 RATE_LIMIT_UNAVAILABLE Retry-After: 5 beradi. Rate limiter bajarishga ruxsat bera olmadi; bu servis kaliti autentifikatsiyasi emas. Read retry’ni yoqish mumkin; xarid esa avtomatik qaytarilmay, tekshirish uchun xato beradi.']),response:'{"ok":false,"error":"Too many requests","error_code":"FLOOD_WAIT","retry_after":42,"flood_wait":42}'},
  {slug:'guides/errors',group:'guides',title:locale('API errors, ambiguous payments, and transport failures','Ошибки API, неопределённые платежи и сетевые сбои','API xatolari, noaniq to‘lovlar va tarmoq uzilishi'),description:locale('Distinguish validation, API, flood-wait, unavailable, malformed-response, and transport errors without exposing credentials.','Различайте ошибки параметров, API, flood wait, недоступности, ответа и сети без раскрытия секретов.','Validation, API, flood wait, unavailable, malformed response va transport xatolarini secretlarni chiqarmasdan ajrating.'),body:locale(
    ['SDK error categories separate local validation, server API failure, rate limiting, temporary unavailability, malformed JSON/response, and network timeout. Safe error messages do not contain request headers or raw transport exception text.','Check HTTP status and ok together. A syntactically valid JSON response with ok=false is not success even on HTTP 200. API failures may use error, reason, or info; response metadata can contain future fields.','A payment marked unconfirmed or carrying tx_hash must be reconciled, not replayed. The SDK does not invent an order lookup endpoint, guarantee delivery timing, or claim idempotency that the backend lacks.'],
    ['SDK разделяют локальную валидацию, ошибку API, rate limit, временную недоступность, неправильный JSON/ответ и timeout сети. Безопасное сообщение не включает заголовки или исходный текст исключения транспорта.','Проверяйте одновременно HTTP-статус и ok. JSON с ok=false не является успехом даже при HTTP 200. Ошибки могут использовать error, reason или info; дополнительные поля сохраняются.','Платёж с unconfirmed или tx_hash нужно сверить, а не повторить. SDK не выдумывает endpoint поиска заказа, время доставки или отсутствующую гарантию идемпотентности.'],
    ['SDK lokal validatsiya, API xatosi, rate limit, vaqtinchalik mavjud emaslik, noto‘g‘ri JSON/javob va tarmoq timeout’ini ajratadi. Xavfsiz xato matnida headerlar yoki transport exception’ining xom matni yo‘q.','HTTP status va ok’ni birga tekshiring. HTTP 200 bo‘lsa ham ok=false JSON muvaffaqiyat emas. Xatoda error, reason yoki info ishlatilishi mumkin; qo‘shimcha maydonlar saqlanadi.','unconfirmed yoki tx_hash qaytgan to‘lovni qayta yubormasdan tekshiring. SDK mavjud bo‘lmagan order lookup endpoint, yetkazish muddati yoki idempotency kafolatini va’da qilmaydi.'])},
  {slug:'guides/credentials',group:'guides',title:locale('Protect wallet credentials in API integrations','Защита данных кошелька при интеграции API','API integratsiyasida hamyon credentiallarini himoyalash'),description:locale('Use server-side wallet secrets, redacted logging, and understand the API operator trust boundary.','Серверные секреты, редактирование логов и граница доверия к оператору API.','Serverdagi secretlar, redacted loglar hamda API operatorining trust chegarasi haqida.'),body:locale(
    ['A mnemonic controls the wallet. A Fragment cookie controls the supplied session. Never include them in public documentation, CI logs, browser bundles, or localStorage.','Purchase requests transmit these sensitive credentials to the API operator. SDK masking applies to client-side diagnostics only.','All documentation uses environment-variable references or clearly synthetic fixtures. Redirects are disabled in SDK transports; do not enable HTTP debug logging around these calls.'],
    ['Mnemonic даёт контроль над кошельком, cookie Fragment — над сессией. Не помещайте их в публичные документы, CI-логи, frontend или localStorage.','Запросы на покупку передают эти чувствительные данные оператору API. Маскирование SDK относится только к клиентской диагностике.','В документации используются переменные окружения или явно синтетические значения. Транспорты SDK не следуют redirect; не включайте HTTP debug-логирование этих запросов.'],
    ['Mnemonic hamyonni, Fragment cookie esa sessiyani boshqarish huquqini beradi. Ularni public hujjat, CI log, frontend yoki localStorage’ga qo‘ymang.','Xarid so‘rovlari bu sensitive credentiallarni API operatoriga uzatadi. SDK masking faqat client diagnostikasiga tegishli.','Hujjatlarda environment variable yoki aniq synthetic qiymatlar ishlatiladi. SDK transportlari redirect’ga ergashmaydi; bu so‘rovlar uchun HTTP debug logging’ni yoqmang.']),sensitive:true},
  {slug:'guides/premium-gifts',group:'guides',title:locale('Integrate Telegram Premium gifts into your backend','Интеграция подарков Telegram Premium в backend','Backend’da Telegram Premium sovg‘asini integratsiya qilish'),description:locale('A practical Premium-gift flow: validate recipient, select 3/6/12 months, perform one purchase, and reconcile ambiguous responses.','Практический сценарий Premium: получатель, 3/6/12 месяцев, одна покупка и сверка неопределённого ответа.','Premium gift oqimi: qabul qiluvchi, 3/6/12 oy, bir martalik xarid va noaniq javobni tekshirish.'),body:locale(
    ['First check the username with get-user-info and inspect is_premium. Collect an explicit duration of 3, 6, or 12 months. Configure wallet version/address to match the wallet connected to Fragment.','Perform exactly one buy-premium call. Record your own internal intent and its outcome without writing the mnemonic to application logs. If the call times out, stop and reconcile; a second POST is a new purchase.','Use mocked transports for integration tests. No real Stars or Premium purchase is needed to verify form mapping, rate-limit handling, or error behavior.'],
    ['Сначала вызовите get-user-info и проверьте is_premium. Выберите ровно 3, 6 или 12 месяцев. Версия и адрес кошелька должны соответствовать подключённому к Fragment кошельку.','Выполните один buy-premium. Сохраните внутреннее намерение и результат без mnemonic в логах. При timeout остановитесь и сверяйте состояние: второй POST — новая покупка.','Тестируйте интеграцию на mocked transport. Реальная покупка не нужна для проверки form data, rate limit и ошибок.'],
    ['Avval get-user-info orqali username va is_premium’ni tekshiring. 3, 6 yoki 12 oyni aniq tanlang. Wallet versiyasi/manzili Fragment’ga ulangan hamyonga mos bo‘lsin.','Bir marta buy-premium chaqiring. Ichki xarid niyati va natijani logga mnemonic yozmasdan qayd eting. Timeout bo‘lsa to‘xtab holatni tekshiring: ikkinchi POST yangi xarid hisoblanadi.','Integratsiyani mocked transport bilan test qiling. Form data, rate limit va xatolarni tekshirish uchun real xarid kerak emas.']),code:'POST /buy-premium/\nContent-Type: application/x-www-form-urlencoded\n\nusername=durov&duration=3&payment_method=usdt_ton',sensitive:true},
  {slug:'faq',group:'guides',title:locale('Fragment Donor API and SDK FAQ','Вопросы об API и SDK Fragment Donor','Fragment Donor API va SDK haqida savollar'),description:locale('Answers about no service auth, required wallet credentials, browser support, retries, package publication, and search visibility.','Ответы об авторизации сервиса, данных кошелька, браузере, повторах, публикации пакетов и поиске.','Servis autentifikatsiyasi, hamyon credentiallari, brauzer, retry, paket nashri va qidiruv haqida javoblar.'),body:locale(
    ['Do I need a service key? No. Api-Key, if supplied, belongs to TonConsole. Do purchases need wallet data? Yes: no service authentication does not mean no wallet credentials.','Can Node.js purchase code run in a browser? No. Browser Cookie header restrictions and mnemonic exposure make purchase integrations server-only. Can I retry a timed-out purchase? Not automatically; reconcile first.','Is this official? No. Are all packages published? Consult the publication-status report and registry links; source availability is not a registry release. Does publishing guarantee Google indexing? No: technical readiness, submission, indexing, and search appearance are separate states.'],
    ['Нужен ли ключ сервиса? Нет. Api-Key, если указан, относится к TonConsole. Нужны ли данные кошелька для покупки? Да: отсутствие авторизации сервиса не отменяет данные кошелька.','Можно ли покупать из браузера через Node.js SDK? Нет: ограничения Cookie и раскрытие mnemonic требуют server-side интеграции. Повторить покупку после timeout? Не автоматически; сначала сверяйте состояние.','Проект официальный? Нет. Все пакеты опубликованы? Проверяйте publication-status и реестры: исходники не равны release. Публикация гарантирует Google? Нет: готовность, отправка, индексирование и поисковая видимость различаются.'],
    ['Servis kaliti kerakmi? Yo‘q. Api-Key berilsa TonConsole’ga tegishli. Xarid uchun hamyon ma’lumoti kerakmi? Ha: servis autentifikatsiyasi yo‘qligi hamyon credentiallari kerak emas degani emas.','Node.js SDK bilan brauzerdan xarid qilsa bo‘ladimi? Yo‘q: Cookie cheklovi va mnemonic oshkor bo‘lishi sabab server-side integratsiya talab qilinadi. Timeout’dan keyin xaridni qaytarsam bo‘ladimi? Avtomatik emas, avval holatni tekshiring.','Bu rasmiy loyihami? Yo‘q. Barcha paket nashr qilinganmi? publication-status va registrni tekshiring: source mavjudligi release degani emas. Publish Google’da chiqishni kafolatlaydimi? Yo‘q: tayyorlik, submission, indekslash va qidiruvda ko‘rinish alohida holatlar.'])},
  {slug:'guides/telegram-stars-api',group:'guides',sensitive:true,title:locale('Telegram Stars API: send Stars to a username','API Telegram Stars: отправка Stars по username','Telegram Stars API: username’ga Stars yuborish'),description:locale('Use a server-side API and seven SDKs to validate a Telegram username and send 50–1,000,000 Stars with TON or USDT.','Серверный API и семь SDK для проверки username и отправки 50–1 000 000 Telegram Stars с оплатой TON или USDT.','Telegram username’ni tekshirish va TON yoki USDT bilan 50–1 000 000 Stars yuborish uchun server API va yetti SDK.'),body:locale(
    ['This API is for gifting Telegram Stars to a recipient username. It is different from accepting Stars as payment for digital goods inside a bot or Mini App through the Telegram Bot Payments API.','A backend first checks the recipient with GET /get-user-info/, then sends one form-urlencoded POST /buy-stars/ request. The amount must be an integer from 50 to 1,000,000; payment_method is usdt_ton or ton.','Purchase calls require the operator-facing wallet mnemonic and Fragment session cookie. Keep both on the server, never in browser code. A timeout does not prove failure, so do not automatically repeat the POST.','Choose the SDK for your existing backend: Python, Node.js/TypeScript, PHP, .NET, Go, Rust, or Ruby. All seven preserve unknown fields, decimal balance strings, retry hints, and uncertain purchase outcomes.'],
    ['Этот API предназначен для отправки Telegram Stars получателю по username. Это не приём Stars за цифровые товары внутри бота или Mini App через Telegram Bot Payments API.','Backend сначала проверяет получателя через GET /get-user-info/, затем один раз отправляет form-urlencoded POST /buy-stars/. amount — целое от 50 до 1 000 000; payment_method — usdt_ton или ton.','Для покупки оператору API передаются mnemonic кошелька и cookie сессии Fragment. Храните их только на сервере. Timeout не доказывает сбой, поэтому не повторяйте POST автоматически.','Выберите SDK своего backend: Python, Node.js/TypeScript, PHP, .NET, Go, Rust или Ruby. Все семь сохраняют дополнительные поля, decimal-балансы, подсказки ожидания и неопределённый исход покупки.'],
    ['Bu API Telegram username’ga Stars sovg‘a qilish uchun. U bot yoki Mini App ichida raqamli mahsulot uchun Stars qabul qiladigan Telegram Bot Payments API’dan farq qiladi.','Backend avval GET /get-user-info/ orqali qabul qiluvchini tekshiradi, keyin form-urlencoded POST /buy-stars/ so‘rovini bir marta yuboradi. amount 50–1 000 000 oralig‘idagi butun son; payment_method usdt_ton yoki ton.','Xarid uchun API operatoriga hamyon mnemonic’i va Fragment session cookie yuboriladi. Ikkalasini faqat serverda saqlang. Timeout muvaffaqiyatsizlikni isbotlamaydi, shuning uchun POST’ni avtomatik takrorlamang.','Mavjud backend’ingizga mos Python, Node.js/TypeScript, PHP, .NET, Go, Rust yoki Ruby SDK’ni tanlang. Yetti SDK qo‘shimcha maydonlar, decimal balanslar, kutish ko‘rsatmalari va noaniq xarid natijalarini saqlaydi.']),code:'curl -X POST https://fragment.donor.uz/buy-stars/ \\\n  -H "Cookie: $FRAGMENT_COOKIE" -H "Mnemonic: $WALLET_MNEMONIC" \\\n  --data-urlencode "username=durov" --data "amount=100" \\\n  --data "payment_method=usdt_ton"'},
  {slug:'guides/send-telegram-stars-to-username',group:'guides',sensitive:true,title:locale('How to send Telegram Stars to a username','Как отправить Telegram Stars пользователю по username','Telegram username’ga Stars qanday yuboriladi'),description:locale('A practical recipient-check, wallet-balance, purchase, and reconciliation flow for sending Telegram Stars to an @username.','Практический процесс проверки получателя, баланса, покупки и сверки при отправке Stars по @username.','@username’ga Stars yuborish uchun qabul qiluvchi, balans, xarid va natijani tekshirish bo‘yicha amaliy oqim.'),body:locale(
    ['Step 1: normalize the recipient username and call get-user-info without wallet headers. Stop if the recipient is invalid. Step 2: read the wallet balance on the backend and keep TON and USDT values as decimal strings.','Step 3: record one internal purchase intent with the username, Stars amount, and chosen payment method. Step 4: submit buy-stars exactly once with the mnemonic and Fragment cookie supplied at runtime.','Step 5: treat only HTTP success with ok=true as the returned success state. Preserve tx_hash and other unknown response fields. For 429, 503, timeout, malformed response, or unconfirmed=true, surface the result for reconciliation instead of resubmitting the purchase.','Use an injected mock transport in automated tests. You can verify request fields, error handling, redaction, and no-duplicate behavior without spending real wallet funds.'],
    ['Шаг 1: нормализуйте username получателя и вызовите get-user-info без заголовков кошелька. Остановитесь, если получатель некорректен. Шаг 2: прочитайте баланс на backend и храните TON/USDT как decimal-строки.','Шаг 3: запишите одно внутреннее намерение покупки: username, количество Stars и способ оплаты. Шаг 4: один раз вызовите buy-stars с mnemonic и cookie Fragment, полученными во время выполнения.','Шаг 5: возвращённый успех — только HTTP success с ok=true. Сохраните tx_hash и дополнительные поля. При 429, 503, timeout, неверном ответе или unconfirmed=true отправьте результат на сверку, а не повторяйте покупку.','В автотестах используйте внедряемый mock transport. Поля, ошибки, редактирование секретов и отсутствие дублей проверяются без расходования реальных средств.'],
    ['1-qadam: qabul qiluvchi username’ni normallashtirib, hamyon headerlarisiz get-user-info chaqiring. Username noto‘g‘ri bo‘lsa to‘xtang. 2-qadam: backend’da balansni o‘qing va TON/USDT qiymatlarini decimal string sifatida saqlang.','3-qadam: username, Stars miqdori va to‘lov usuli bilan bitta ichki xarid niyatini yozib qo‘ying. 4-qadam: runtime’da olingan mnemonic va Fragment cookie bilan buy-stars’ni faqat bir marta chaqiring.','5-qadam: faqat muvaffaqiyatli HTTP va ok=true qaytgan holatni muvaffaqiyat deb oling. tx_hash va qo‘shimcha maydonlarni saqlang. 429, 503, timeout, noto‘g‘ri javob yoki unconfirmed=true bo‘lsa xaridni qaytarmasdan tekshiruvga yuboring.','Avtomatik testlarda injected mock transport ishlating. Real mablag‘ sarflamasdan request maydonlari, xatolar, secret redaction va takroriy xarid yo‘qligini tekshirish mumkin.']),code:'GET /get-user-info/?username=durov\nGET /wallet-balance/\nPOST /buy-stars/\n\nusername=durov&amount=100&payment_method=usdt_ton'},
  {slug:'guides/telegram-premium-gift-api',group:'guides',sensitive:true,title:locale('Telegram Premium Gift API for a username','API подарка Telegram Premium по username','Username uchun Telegram Premium Gift API'),description:locale('Validate a recipient and gift 3, 6, or 12 months of Telegram Premium through a server-side API with safe payment handling.','Проверка получателя и подарок Telegram Premium на 3, 6 или 12 месяцев через серверный API.','Qabul qiluvchini tekshirib, server API orqali 3, 6 yoki 12 oylik Telegram Premium sovg‘a qilish.'),body:locale(
    ['Use the Premium gift endpoint when your backend needs to send a subscription to a Telegram username. Check get-user-info first and inspect is_premium before offering the purchase.','POST /buy-premium/ accepts username, duration, and payment_method as form data. duration is exactly 3, 6, or 12; payment_method is usdt_ton or ton. The request uses the same protected wallet headers as a Stars purchase.','Create only one purchase request for the user’s explicit choice. Never silently change the duration, send both Premium and Stars, or retry after a timeout. Reconcile the recipient and wallet state before a new intentional purchase.','The seven SDK packages expose the same operation with native language naming and typed error categories. Test with synthetic fixtures and an injected transport instead of a real purchase.'],
    ['Используйте endpoint Premium, когда backend должен отправить подписку по Telegram username. Сначала вызовите get-user-info и проверьте is_premium.','POST /buy-premium/ принимает username, duration и payment_method как form data. duration — ровно 3, 6 или 12; payment_method — usdt_ton или ton. Используются те же защищённые заголовки кошелька, что и для Stars.','Создавайте только одну покупку по явному выбору пользователя. Не меняйте срок, не отправляйте одновременно Premium и Stars и не повторяйте запрос после timeout. Перед новой покупкой сверяйте получателя и кошелёк.','Семь SDK предоставляют одну операцию с naming языка и типизированными ошибками. Тестируйте на синтетических fixtures и внедряемом transport без реальной покупки.'],
    ['Backend Telegram username’ga obuna yuborishi kerak bo‘lsa Premium endpoint’dan foydalaning. Avval get-user-info chaqirib, is_premium holatini tekshiring.','POST /buy-premium/ form data sifatida username, duration va payment_method oladi. duration faqat 3, 6 yoki 12; payment_method usdt_ton yoki ton. So‘rov Stars xarididagi himoyalangan hamyon headerlarini ishlatadi.','Foydalanuvchining aniq tanlovi uchun faqat bitta xarid yarating. Muddatni yashirin o‘zgartirmang, Premium va Stars’ni birga yubormang, timeout’dan keyin qaytarmang. Yangi xariddan oldin qabul qiluvchi va hamyon holatini tekshiring.','Yetti SDK bir xil operatsiyani tilga mos naming va typed xatolar bilan beradi. Real xarid o‘rniga synthetic fixture va injected transport bilan test qiling.']),code:'curl -X POST https://fragment.donor.uz/buy-premium/ \\\n  -H "Cookie: $FRAGMENT_COOKIE" -H "Mnemonic: $WALLET_MNEMONIC" \\\n  --data-urlencode "username=durov" --data "duration=3" \\\n  --data "payment_method=usdt_ton"'},
  {slug:'guides/telegram-stars-api-vs-bot-api',group:'guides',title:locale('Telegram Stars API vs Bot Payments API','Telegram Stars API и Bot Payments API: различия','Telegram Stars API va Bot Payments API farqi'),description:locale('Choose between gifting Stars to a username and accepting Stars for digital goods inside a Telegram bot or Mini App.','Когда нужен подарок Stars по username, а когда — приём Stars за цифровые товары в боте или Mini App.','Username’ga Stars sovg‘a qilish va bot yoki Mini App’da Stars qabul qilish orasidagi farq.'),body:locale(
    ['Choose by the direction of value. To accept Stars from a customer for digital goods inside your bot or Mini App, use Telegram’s official Bot Payments API and XTR invoices. To send or gift Stars to a recipient username from your backend, this independent Fragment Donor API covers that separate workflow.','Bot Payments uses a bot token, invoice or invoice link, pre-checkout handling, and successful_payment updates. Fragment Donor purchase calls instead use a wallet mnemonic and Fragment session cookie on a trusted server. The credentials and risk model are not interchangeable.','For a username gift, validate the recipient, decide one amount, submit one purchase, and reconcile ambiguous results. For selling digital goods, follow Telegram’s official invoice, pre-checkout, fulfillment, and refund documentation.','Fragment Donor is an independent project and is not an official Telegram, Fragment, or TON SDK. Do not describe its packages as official clients.'],
    ['Выбор зависит от направления оплаты. Чтобы принимать Stars от клиента за цифровые товары внутри бота или Mini App, используйте официальный Telegram Bot Payments API и счета XTR. Чтобы отправить Stars получателю по username из backend, независимый Fragment Donor API реализует другой сценарий.','Bot Payments использует bot token, invoice или invoice link, pre-checkout и обновления successful_payment. Fragment Donor использует mnemonic кошелька и cookie Fragment на доверенном сервере. Эти данные и риски нельзя смешивать.','Для подарка проверьте получателя, выберите одно количество, отправьте одну покупку и сверяйте неопределённый результат. Для продажи товаров следуйте официальной документации Telegram по invoice, pre-checkout, исполнению и возвратам.','Fragment Donor — независимый проект, а не официальный SDK Telegram, Fragment или TON. Не называйте его пакеты официальными клиентами.'],
    ['Tanlov pul yo‘nalishiga bog‘liq. Bot yoki Mini App ichida raqamli mahsulot uchun mijozdan Stars qabul qilishda Telegram’ning rasmiy Bot Payments API va XTR invoice ishlatiladi. Backend’dan username’ga Stars yuborish yoki sovg‘a qilish uchun mustaqil Fragment Donor API boshqa oqimni bajaradi.','Bot Payments bot token, invoice yoki invoice link, pre-checkout va successful_payment update’larini ishlatadi. Fragment Donor xaridi esa ishonchli serverda hamyon mnemonic’i va Fragment cookie’sini ishlatadi. Credential va xavf modellari bir xil emas.','Username’ga sovg‘ada qabul qiluvchini tekshiring, bitta miqdorni tanlang, bitta xarid yuboring va noaniq natijani solishtiring. Raqamli mahsulot sotishda Telegram’ning invoice, pre-checkout, fulfillment va refund hujjatlariga amal qiling.','Fragment Donor mustaqil loyiha; Telegram, Fragment yoki TON’ning rasmiy SDK’si emas. Paketlarni rasmiy klient deb ta’riflamang.']),code:'Receive Stars for digital goods -> Telegram Bot Payments API (XTR)\nSend Stars to a username       -> Fragment Donor buy-stars\nGift Premium to a username     -> Fragment Donor buy-premium'},
  {slug:'guides/fragment-api-automation',group:'guides',sensitive:true,title:locale('Fragment API automation for Stars and Premium','Автоматизация Fragment API для Stars и Premium','Stars va Premium uchun Fragment API avtomatizatsiyasi'),description:locale('Automate recipient validation, TON/USDT balance checks, and one-at-a-time Stars or Premium gifts from a server backend.','Автоматизация проверки получателя, баланса TON/USDT и одиночной отправки Stars или Premium с backend.','Backend’da qabul qiluvchi, TON/USDT balans va bir martalik Stars yoki Premium sovg‘asini avtomatlashtirish.'),body:locale(
    ['A safe automation pipeline separates read operations from spending operations. Username lookup and wallet balance may use bounded opt-in retries; Stars and Premium purchases never retry automatically.','Keep one durable internal record for each intended purchase: recipient, product, amount or duration, payment method, creation time, and final or uncertain state. Do not store the mnemonic, Fragment cookie, provider key, or proxy password in that record.','Use a worker with a strict one-purchase-at-a-time policy per intent. If the response is unconfirmed, the connection times out, or the response cannot be parsed, stop that intent and require reconciliation instead of placing a second order.','The service has a shared per-IP minute quota across all four endpoints. Schedule read traffic, honor the longest valid Retry-After hint, and do not let a batch job turn a rate-limit response into duplicate spending.'],
    ['Безопасная автоматизация разделяет чтение и расходование средств. Для username и баланса допустимы ограниченные повторы с явным включением; покупки Stars и Premium автоматически не повторяются.','Для каждого намерения храните одну устойчивую запись: получатель, продукт, количество или срок, способ оплаты, время и финальное либо неопределённое состояние. Не записывайте mnemonic, cookie Fragment, provider key или пароль proxy.','Worker должен выполнять одну покупку на одно намерение. При unconfirmed, timeout или неверном ответе остановите намерение и потребуйте сверку, а не создавайте второй заказ.','Все четыре endpoint делят минутную квоту по IP. Планируйте чтение, учитывайте максимальный корректный Retry-After и не позволяйте batch-задаче превратить rate limit в повторные списания.'],
    ['Xavfsiz avtomatizatsiya o‘qish va mablag‘ sarflash operatsiyalarini ajratadi. Username va balans uchun alohida yoqilgan chegaralangan retry mumkin; Stars va Premium xaridi avtomatik takrorlanmaydi.','Har bir xarid niyati uchun bitta doimiy yozuv saqlang: qabul qiluvchi, mahsulot, miqdor yoki muddat, to‘lov usuli, vaqt va yakuniy yoki noaniq holat. Mnemonic, Fragment cookie, provider key yoki proxy parolini bu yozuvga qo‘ymang.','Worker har bir niyat uchun faqat bitta xarid bajarsin. unconfirmed, timeout yoki o‘qib bo‘lmaydigan javob bo‘lsa niyatni to‘xtatib, ikkinchi order o‘rniga tekshiruv talab qiling.','To‘rtta endpoint bitta IP minutlik limitini bo‘lishadi. Read trafikni rejalashtiring, eng uzun to‘g‘ri Retry-After ko‘rsatmasiga amal qiling va batch job rate limit’ni takroriy xaridga aylantirmasin.']),code:'lookup recipient -> check balance -> create intent -> submit once\n                                            |\n                         success <----------+----------> uncertain -> reconcile'},
  {slug:'guides/payment-timeout-no-retry',group:'guides',title:locale('Payment timeout: prevent duplicate Telegram Stars purchases','Timeout платежа: защита от повторной покупки Telegram Stars','Payment timeout: takroriy Telegram Stars xaridini oldini olish'),description:locale('Why a timed-out Stars or Premium request can have an unknown outcome and must not be automatically retried.','Почему после timeout результат покупки Stars или Premium неизвестен и запрос нельзя автоматически повторять.','Nega timeout’dan keyin Stars yoki Premium xaridi noaniq bo‘ladi va so‘rovni avtomatik qaytarib bo‘lmaydi.'),body:locale(
    ['An HTTP timeout only means the client did not receive a complete response before its deadline. The server or wallet transfer may already have progressed, so retrying the same POST can create a second purchase.','These SDKs mark transport failure, malformed purchase response, redirect, server failure, and explicit unconfirmed=true as an uncertain purchase outcome where applicable. They expose the error without sending a duplicate request.','Record the original intent, preserve a redacted tx_hash or server metadata, and compare the wallet and recipient state. Only a new, explicit human or application decision should create another purchase.','Backend idempotency-key behavior is not documented for these endpoints. A client-generated key therefore cannot be assumed to deduplicate requests.'],
    ['HTTP timeout означает только то, что клиент не получил полный ответ до своего deadline. Сервер или перевод могли продолжить работу, поэтому повтор того же POST способен создать вторую покупку.','SDK отмечают transport failure, неверный ответ покупки, redirect, server failure и явный unconfirmed=true как неопределённый исход там, где это применимо. Ошибка возвращается без второго запроса.','Сохраните исходное намерение, безопасно очищенный tx_hash или metadata и сравните кошелёк с состоянием получателя. Только новое явное решение человека или приложения должно создавать покупку.','Поведение backend Idempotency-Key для этих endpoint не документировано. Нельзя считать, что созданный клиентом ключ удалит дубликаты.'],
    ['HTTP timeout faqat klient deadline ichida to‘liq javob olmaganini bildiradi. Server yoki hamyon transferi davom etgan bo‘lishi mumkin, shu sabab bir xil POST’ni qaytarish ikkinchi xarid yaratishi mumkin.','SDK’lar transport xatosi, noto‘g‘ri purchase javobi, redirect, server xatosi va aniq unconfirmed=true holatini tegishli joyda noaniq xarid natijasi deb belgilaydi. Xato ikkinchi so‘rovsiz qaytariladi.','Dastlabki niyat, redaktlangan tx_hash yoki server metadata’ni saqlab, hamyon va qabul qiluvchi holatini solishtiring. Faqat inson yoki dastur tomonidan yangi aniq qaror boshqa xarid yaratishi kerak.','Bu endpointlar uchun backend Idempotency-Key xatti-harakati hujjatlashtirilmagan. Klient yaratgan key so‘rovlarni deduplicate qiladi deb bo‘lmaydi.']),response:'{"ok":false,"unconfirmed":true,"tx_hash":"SYNTHETIC_UNCONFIRMED_TX_HASH"}'},
];

export const sdkInstall = {
  python: 'python -m pip install fragment-donor-sdk==0.1.3',
  typescript: 'npm install fragment-donor-sdk@0.1.3',
  php: 'composer require fragment-donor/sdk:^0.1',
  dotnet: 'dotnet add package FragmentDonor.Sdk --version 0.1.3',
  go: 'go get github.com/usnuz/fragment-donor-sdk/go@v0.1.3',
  rust: 'cargo add fragment-donor-sdk@0.1.3',
  ruby: 'gem install fragment-donor-sdk -v 0.1.3',
};
const names = {python:'Python',typescript:'Node.js / TypeScript',php:'PHP',dotnet:'C# / .NET',go:'Go',rust:'Rust',ruby:'Ruby'};
const minRuntime = {python:'Python 3.10+',typescript:'Node.js 20+',php:'PHP 8.2+',dotnet:'.NET 8+',go:'Go 1.23+',rust:'Rust 1.99+',ruby:'Ruby 3.2+'};
for (const [id,name] of Object.entries(names)) {
  pages.push({slug:`sdk/${id}`,group:'sdks',sdk:id,sensitive:true,title:locale(`${name} SDK for Telegram Stars and Premium`,`${name} SDK для Telegram Stars и Premium`,`${name} SDK: Telegram Stars va Premium`),description:locale(`Install the independent Fragment Donor ${name} SDK, check usernames, gift Stars/Premium, and handle rate limits safely.`,`Установка независимого SDK Fragment Donor для ${name}: username, подарки Stars/Premium и rate limit.`,`Mustaqil Fragment Donor ${name} SDK’ni o‘rnatish, username, Stars/Premium va rate limit bilan ishlash.`),body:locale(
    [`Runtime: ${minRuntime[id]}. Version 0.1.3 is published; use the exact registry command shown on this page.`,`The client exposes username lookup, Stars purchase, Premium gift, and wallet balance with native naming for ${name}. Required request bodies use form-urlencoded. Wallet balances remain decimal strings; unknown response fields are retained.`,`Configure a request timeout and wallet credentials on your backend. Read retries are opt-in and bounded; purchase calls never retry automatically. Review the package README for the exact constructor and error classes.`],
    [`Runtime: ${minRuntime[id]}. Устанавливайте пакет из реестра только после статуса PUBLISHED; до этого используйте сборку каталога ${id} из public source.`,`Клиент предлагает username, покупку Stars, подарок Premium и баланс с naming, принятым в ${name}. Запросы используют form-urlencoded. Баланс сохраняется decimal-строкой, дополнительные поля не удаляются.`,`Настройте timeout и данные кошелька на backend. Повтор чтения включается явно и ограничен; покупки никогда не повторяются автоматически. Точный constructor и типы ошибок приведены в README пакета.`],
    [`Runtime: ${minRuntime[id]}. Paket registrda PUBLISHED bo‘lgach o‘rnating; ungacha public source ichidagi ${id} katalogidan build/install qiling.`,`Klient ${name} uslubidagi naming bilan username, Stars xaridi, Premium sovg‘asi va balansni beradi. So‘rovlar form-urlencoded. Balans decimal string sifatida, qo‘shimcha maydonlar esa yo‘qolmasdan saqlanadi.`,`Backend’da timeout va hamyon credentiallarini sozlang. Read retry alohida yoqilib chegaralanadi; xaridlar hech qachon avtomatik qaytarilmaydi. Aniq constructor va xato turlari paket README’sida bor.`]),install:sdkInstall[id],packageReadme:`https://github.com/usnuz/fragment-donor-sdk/tree/main/${id}`});
}
pages.push({slug:'sdk',group:'sdks',title:locale('Compare and install seven Fragment Donor SDKs','Сравнение и установка семи SDK Fragment Donor','Yetti Fragment Donor SDK’ni solishtirish va o‘rnatish'),description:locale('One API contract for Python, Node.js, PHP, .NET, Go, Rust, and Ruby. Choose the package matching your backend.','Общий API-контракт для Python, Node.js, PHP, .NET, Go, Rust и Ruby. Выберите SDK своего backend.','Python, Node.js, PHP, .NET, Go, Rust va Ruby uchun bitta API kontrakti. Backend’ingizga mos SDK’ni tanlang.'),body:locale(['Choose the language your backend already uses. All seven packages cover the same four endpoints and intentionally omit service-key authentication.','Package tests use shared synthetic fixtures. Publication and runtime test status are reported independently; an unexecuted build is never called passed.'],['Выберите язык существующего backend. Все семь SDK поддерживают четыре эндпоинта без ключа авторизации сервиса.','Тесты используют общие синтетические fixtures. Статус публикации и runtime-проверки учитывается отдельно; невыполненная сборка не обозначается passed.'],['Mavjud backend tilini tanlang. Yetti SDK bir xil to‘rtta endpointni servis autentifikatsiya kalitisiz qo‘llab-quvvatlaydi.','Testlar umumiy synthetic fixture’lardan foydalanadi. Nashr va runtime test holati alohida qayd etiladi; bajarilmagan build passed deb yozilmaydi.']),code:Object.entries(sdkInstall).map(([id,command])=>`# ${names[id]}\n${command}`).join('\n\n')});
for(const id of ['python','typescript']){
  const name=names[id];
  pages.push({slug:`guides/buy-telegram-stars-${id==='typescript'?'nodejs':id}`,group:'guides',exampleSdk:id,sensitive:true,install:sdkInstall[id],title:locale(`Buy Telegram Stars with ${name}: safe server integration`,`${name}: безопасная интеграция покупки Telegram Stars`,`${name} orqali Telegram Stars xaridi: xavfsiz integratsiya`),description:locale(`A ${name} backend workflow for username checks, wallet balance, Telegram Stars/Premium gifts and 429 handling without duplicate purchase retries.`,`${name} backend: username, баланс, подарки Telegram Stars/Premium и 429 без автоматического повторения покупки.`,`${name} backend uchun username, balans, Telegram Stars/Premium va takroriy xaridsiz 429 ishlovi.`),body:locale(
    [`Start with a public username lookup in ${name}. It needs no account or wallet credential. Check the publication report before installing the registry version; alternatively build the corresponding source directory.`,`Load the wallet mnemonic and Fragment session at runtime. Read balance first; balances are decimal strings. The sample enables purchases only with FRAGMENT_ALLOW_PURCHASES=yes and FRAGMENT_PURCHASE_KIND=stars or premium; exactly one selected gift.`,`Decide on one intended gift: Stars amount 50–1,000,000 or Premium duration 3/6/12. The example shows both API methods for reference, not an instruction to execute both gifts. Each purchase spends real funds.`,`Catch the typed flood-wait error and surface its wait hint to your job scheduler. Never automatically resubmit the purchase. After a timeout or unconfirmed transaction, reconcile wallet/recipient state before a new intentional submission.`],
    [`Начните с публичной проверки username через ${name}: аккаунт сервиса и данные кошелька не нужны. Проверьте статус пакета до установки или соберите SDK из исходного каталога.`,`Передайте mnemonic кошелька и сессию Fragment во время выполнения. Сначала проверьте баланс, сохраняя decimal-строки. Покупки в примере требуют FRAGMENT_ALLOW_PURCHASES=yes и FRAGMENT_PURCHASE_KIND=stars либо premium; выполняется только один выбранный подарок.`,`Выберите один нужный подарок: 50–1 000 000 Stars или Premium на 3/6/12 месяцев. Оба метода показаны для справки, а не как команда выполнить две покупки. Каждая покупка расходует реальные средства.`,`Обработайте типизированный flood-wait и передайте время ожидания планировщику. Не повторяйте покупку автоматически. После timeout/unconfirmed сверяйте кошелёк и получателя перед новым намеренным запросом.`],
    [`Avval ${name} orqali public username tekshiruvini bajaring: servis akkaunti va hamyon credentiali kerak emas. Paketni o‘rnatishdan avval nashr holatini tekshiring yoki tegishli source katalogini build qiling.`,`Hamyon mnemonic’i va Fragment sessiyasini runtime vaqtida uzating. Avval balansni tekshiring va decimal stringni saqlang. Misolda xarid uchun FRAGMENT_ALLOW_PURCHASES=yes va FRAGMENT_PURCHASE_KIND=stars yoki premium kerak; faqat bitta tanlangan sovg‘a bajariladi.`,`Bitta kerakli sovg‘ani tanlang: 50–1 000 000 Stars yoki 3/6/12 oylik Premium. Misolda ikkala API methodi ma’lumot uchun ko‘rsatilgan, bu ikki xaridni ham bajarish topshirig‘i emas. Har bir xarid haqiqiy mablag‘ sarflaydi.`,`Typed flood-wait xatosini tuting va kutish muddatini job scheduler’ga uzating. Xaridni avtomatik qaytarmang. Timeout/unconfirmed bo‘lsa yangi ataylab yuborilgan so‘rovdan oldin hamyon va qabul qiluvchi holatini tekshiring.`])});
}
const unknownPurchaseExplanation=locale(
  'HTTP 400 with ok=false and unconfirmed=true raises PurchaseOutcomeUnknownError (or the native equivalent), with outcome_unknown=true and safely redacted details including tx_hash. This is not an ordinary validation rejection: funds may already have been sent. Reconcile manually; no automatic purchase retry.',
  'HTTP 400 с ok=false и unconfirmed=true вызывает PurchaseOutcomeUnknownError (или аналог языка), с outcome_unknown=true и безопасно очищенными details, включая tx_hash. Это не обычный отказ валидации: средства уже могли уйти. Сверьте вручную; автоматического повтора покупки нет.',
  'HTTP 400, ok=false va unconfirmed=true bo‘lsa PurchaseOutcomeUnknownError (yoki tilga mos xato), outcome_unknown=true va tx_hash kabi xavfsiz redaktlangan details qaytadi. Bu oddiy validation rad javobi emas: mablag‘ allaqachon yuborilgan bo‘lishi mumkin. Qo‘lda tekshiring; xarid avtomatik takrorlanmaydi.'
);
for(const lang of languages)pages.find(page=>page.slug==='guides/errors').body[lang].push(unknownPurchaseExplanation[lang]);
